FILE packages/template-engine/src/transformer.ts
0001: import { evaluate } from './evaluator.js';
0002: import type { RenderContext, RenderOptions } from './types.js';
0003: 
0004: const EXPR_REGEX = /\{\{([^}]+(?:\}[^}]+)*)\}\}/g;
0005: const EACH_REGEX = /^\{\{#each\s+(.+?)\}\}$/;
0006: const IF_REGEX = /^\{\{#if\s+(.+?)\}\}$/;
0007: const ELSEIF_REGEX = /^\{\{#elseif\s+(.+?)\}\}$/;
0008: const ELSE_REGEX = /^\{\{#else\}\}$/;
0009: 
0010: function interpolateString(str: string, context: RenderContext, options?: RenderOptions): unknown {
0011:   const singleMatch = str.match(/^\{\{([^}]+(?:\}[^}]+)*)\}\}$/);
0012:   if (singleMatch) {
0013:     const value = evaluate(singleMatch[1].trim(), context, options);
0014:     return value === undefined ? str : value;
0015:   }
0016: 
0017:   return str.replace(EXPR_REGEX, (_, expr) => {
0018:     const val = evaluate(expr.trim(), context, options);
0019:     return val === undefined || val === null ? '' : String(val);
0020:   });
0021: }
0022: 
0023: function resolvedKey(key: string, context: RenderContext, options?: RenderOptions): string {
0024:   return key.includes('{{') && !key.startsWith('{{#')
0025:     ? String(interpolateString(key, context, options))
0026:     : key;
0027: }
0028: 
0029: function safeDefine(target: Record<string, unknown>, key: string, value: unknown): void {
0030:   Object.defineProperty(target, key, {
0031:     value,
0032:     enumerable: true,
0033:     writable: true,
0034:     configurable: true,
0035:   });
0036: }
0037: 
0038: interface ResolvedEntry {
0039:   key: string;
0040:   value: unknown;
0041:   transformedType?: unknown;
0042: }
0043: 
0044: function processObject(
0045:   obj: Record<string, unknown>,
0046:   context: RenderContext,
0047:   options?: RenderOptions,
0048: ): unknown {
0049:   const keys = Object.keys(obj);
0050: 
0051:   for (const key of keys) {
0052:     const eachMatch = key.match(EACH_REGEX);
0053:     if (eachMatch) {
0054:       const items = evaluate(eachMatch[1].trim(), context, options);
0055:       if (!Array.isArray(items)) return [];
0056:       const template = obj[key];
0057:       return items.map((item, index) => transform(template, {
0058:         ...context,
0059:         $jason: item,
0060:         $root: context.$jason,
0061:         $index: index,
0062:       }, options));
0063:     }
0064:   }
0065: 
0066:   if (keys.some(key => IF_REGEX.test(key))) {
0067:     return processConditionalChain(obj, keys, context, options);
0068:   }
0069: 
0070:   const result: Record<string, unknown> = {};
0071:   if (options?.preserveHtmlText !== true) {
0072:     for (const key of keys) {
0073:       const outputKey = resolvedKey(key, context, options);
0074:       safeDefine(result, outputKey, transform(obj[key], context, options));
0075:     }
0076:     return result;
0077:   }
0078: 
0079:   // Body mode deliberately resolves the complete key set before classifying or
0080:   // transforming values. This makes classification independent of authored order.
0081:   const entries: ResolvedEntry[] = keys.map(key => ({
0082:     key: resolvedKey(key, context, options),
0083:     value: obj[key],
0084:   }));
0085: 
0086:   for (const entry of entries) {
0087:     if (entry.key === 'type') {
0088:       entry.transformedType = transform(entry.value, context, options);
0089:     }
0090:   }
0091: 
0092:   let finalType: unknown;
0093:   for (const entry of entries) {
0094:     if (entry.key === 'type') finalType = entry.transformedType;
0095:   }
0096:   const protectText = typeof finalType === 'string' && finalType === 'html';
0097: 
0098:   for (const entry of entries) {
0099:     const output = entry.key === 'type'
0100:       ? entry.transformedType
0101:       : (protectText && entry.key === 'text'
0102:         ? entry.value
0103:         : transform(entry.value, context, options));
0104:     safeDefine(result, entry.key, output);
0105:   }
0106:   return result;
0107: }
0108: 
0109: function processConditionalChain(
0110:   obj: Record<string, unknown>,
0111:   keys: string[],
0112:   context: RenderContext,
0113:   options?: RenderOptions,
0114: ): unknown {
0115:   for (const key of keys) {
0116:     const match = key.match(IF_REGEX) || key.match(ELSEIF_REGEX);
0117:     if (match) {
0118:       if (evaluate(match[1].trim(), context, options)) return transform(obj[key], context, options);
0119:       continue;
0120:     }
0121:     if (ELSE_REGEX.test(key)) return transform(obj[key], context, options);
0122:   }
0123:   return undefined;
0124: }
0125: 
0126: /** Transform template expressions and structural directives recursively. */
0127: export function transform(value: unknown, context: RenderContext, options?: RenderOptions): unknown {
0128:   if (value === null || value === undefined) return value;
0129:   if (typeof value === 'string') return interpolateString(value, context, options);
0130: 
0131:   if (Array.isArray(value)) {
0132:     const isConditionalObject = (item: unknown): boolean => (
0133:       typeof item === 'object' && item !== null && !Array.isArray(item) &&
0134:       Object.keys(item).length > 0 &&
0135:       Object.keys(item).every(key => IF_REGEX.test(key) || ELSEIF_REGEX.test(key) || ELSE_REGEX.test(key))
0136:     );
0137: 
0138:     if (value.length > 0 && value.every(isConditionalObject)) {
0139:       for (const item of value) {
0140:         for (const key of Object.keys(item as Record<string, unknown>)) {
0141:           const match = key.match(IF_REGEX) || key.match(ELSEIF_REGEX);
0142:           if (match) {
0143:             if (evaluate(match[1].trim(), context, options)) {
0144:               return transform((item as Record<string, unknown>)[key], context, options);
0145:             }
0146:             continue;
0147:           }
0148:           if (ELSE_REGEX.test(key)) return transform((item as Record<string, unknown>)[key], context, options);
0149:         }
0150:       }
0151:       return undefined;
0152:     }
0153: 
0154:     return value.flatMap(item => {
0155:       const output = transform(item, context, options);
0156:       // Preserve the established array behavior for a missing standalone
0157:       // expression while allowing unresolved object fields to remain authored.
0158:       if (options?.preserveHtmlText !== true && typeof item === 'string' && /^\{\{[^}]+\}\}$/.test(item) && output === item) return [];
0159:       return Array.isArray(output) ? output : [output];
0160:     }).filter(item => item !== undefined);
0161:   }
0162: 
0163:   if (typeof value === 'object') return processObject(value as Record<string, unknown>, context, options);
0164:   return value;
0165: }
